/**
 * ArticlesPage - Weekly digest articles generated by Lyra.
 *
 * Serves three modes, resolved from the route payload (react-ssr Task 13):
 *
 * - `article`: /articles/{slug} — the payload carries the whole issue
 *   including body_html (Python-markdown, nh3-sanitized), so the first
 *   render is the complete journal with no fetch.
 * - `articleIndex`: /articles/ — the crawlable hub, rendered from the
 *   payload's article list. No fetch either.
 * - no payload: the standalone /articles.html SPA — newspaper layout,
 *   hash routing (#slug), self-fetched data. This mode is a product
 *   decision and must keep working unchanged (see articlesMain.tsx).
 *
 * Share URLs use the canonical SEO path: /articles/{slug}
 */

import { useState, useEffect, useMemo } from 'react'
import { useIsFounder } from '../hooks/useIsFounder'
import Breadcrumbs from '../components/layout/Breadcrumbs'
import ThumbsFeedback from '../components/feedback/ThumbsFeedback'
import CommunityCta from '../components/layout/CommunityCta'
import PageHeader from '../components/layout/PageHeader'
import AiNoticeBanner from '../components/layout/AiNoticeBanner'
import { useRoute } from '../seo/RouteContext'
import type { ArticleIndexRoute, ArticleRoute } from '../types/anRoute'

import JournalArticle from '../components/news/JournalArticle'
import JournalHub from '../components/news/JournalHub'
import JournalQualityReportPanel from '../components/news/JournalQualityReport'
import '../components/news/news-cards.css'
import '../styles/story-page.css'
import { slugify } from '../seo/meta'
import { shareOrCopy } from '../utils/share'

// Share/copy/Medium need only the title; both payload views carry it.
function articlePath(article: { title: string }): string {
  return `/articles/${slugify(article.title)}`
}

function shareUrl(article: { title: string }): string {
  return `https://ancientnerds.com${articlePath(article)}`
}


/** TOC sidebar component. */
/**
 * Überschriften aus fertigem body_html — die SEO-Ansicht bekommt HTML, kein
 * Markdown, kann extractHeadings() also nicht benutzen. Der Anker kommt aus
 * dem id-Attribut, das article_html_renderer._heading_anchors setzt: so kann
 * der Link nicht danebenzeigen, weil beide dieselbe Quelle lesen.
 */
function extractHtmlHeadings(html: string): { text: string; slug: string }[] {
  return [...html.matchAll(/<h2 id="([^"]+)">(.*?)<\/h2>/gs)].map(m => ({
    slug: m[1],
    text: m[2].replace(/<[^>]+>/g, '').trim(),
  }))
}

/**
 * Scroll-Spy für das Inhaltsverzeichnis: welche Überschrift steht gerade
 * oben. Beide Leseansichten (SPA und SEO) benutzen ihn.
 *
 * Der Observer wird im Effekt-Cleanup getrennt, nicht im Timeout — ein
 * return aus dem Timeout-Callback verpufft, so blieb der alte Observer bei
 * jedem Artikelwechsel am Leben.
 */
function useActiveHeading(headings: { slug: string }[], enabled: boolean): string | null {
  const [active, setActive] = useState<string | null>(null)
  useEffect(() => {
    if (!enabled || headings.length === 0) {
      setActive(null)
      return
    }
    let observer: IntersectionObserver | null = null
    // Kurze Verzögerung, bis die Überschriften im DOM stehen.
    const timer = setTimeout(() => {
      const elements = headings
        .map(h => document.getElementById(h.slug))
        .filter((el): el is HTMLElement => el !== null)
      if (elements.length === 0) return
      observer = new IntersectionObserver(
        entries => {
          for (const entry of entries) {
            if (entry.isIntersecting) {
              setActive(entry.target.id)
              break
            }
          }
        },
        { rootMargin: '-80px 0px -70% 0px', threshold: 0 },
      )
      elements.forEach(el => observer!.observe(el))
    }, 100)
    return () => {
      clearTimeout(timer)
      observer?.disconnect()
    }
  }, [enabled, headings])
  return active
}

function TableOfContents({ headings, activeSlug }: {
  headings: { text: string; slug: string }[]
  activeSlug: string | null
}) {
  if (headings.length === 0) return null
  return (
    <nav className="articles-toc">
      <span className="articles-toc-label">Contents</span>
      <ul className="articles-toc-list">
        {headings.map(h => (
          <li key={h.slug} className={h.slug === activeSlug ? 'active' : ''}>
            <a href={`#${h.slug}`} onClick={e => {
              e.preventDefault()
              document.getElementById(h.slug)?.scrollIntoView({ behavior: 'smooth' })
            }}>
              {h.text}
            </a>
          </li>
        ))}
      </ul>
    </nav>
  )
}


function ShareButton({ article }: { article: { title: string } }) {
  const [copied, setCopied] = useState(false)

  const handleShare = async () => {
    const result = await shareOrCopy(article.title, shareUrl(article))
    if (result !== 'copied') return
    setCopied(true)
    setTimeout(() => setCopied(false), 1500)
  }

  return (
    <button className="articles-share-btn" onClick={handleShare} title="Share journal">
      <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
        <path d="M4 12v8a2 2 0 002 2h12a2 2 0 002-2v-8" />
        <polyline points="16 6 12 2 8 6" />
        <line x1="12" y1="2" x2="12" y2="15" />
      </svg>
      {copied ? 'Copied!' : 'Share'}
    </button>
  )
}

function MediumButton({ article }: { article: { title: string } }) {
  // Founders-only editorial tool: opens the light-themed copy template
  // with the canonical URL for Medium's canonical-link setting.
  return (
    <button
      className="articles-share-btn"
      onClick={() => window.open(`/articles/${slugify(article.title)}/medium`, '_blank')}
      title="Copy for Medium (founders only)"
    >
      <svg width="14" height="14" viewBox="0 0 24 24" fill="currentColor">
        <path d="M13.54 12a6.8 6.8 0 01-6.77 6.82A6.8 6.8 0 010 12a6.8 6.8 0 016.77-6.82A6.8 6.8 0 0113.54 12zM20.96 12c0 3.54-1.51 6.42-3.38 6.42-1.87 0-3.39-2.88-3.39-6.42s1.52-6.42 3.39-6.42 3.38 2.88 3.38 6.42M24 12c0 3.17-.53 5.75-1.19 5.75-.66 0-1.19-2.58-1.19-5.75s.53-5.75 1.19-5.75C23.47 6.25 24 8.83 24 12z" />
      </svg>
      Medium
    </button>
  )
}

function CopyLinkButton({ article }: { article: { title: string } }) {
  const [copied, setCopied] = useState(false)

  const handleCopy = async () => {
    await navigator.clipboard.writeText(shareUrl(article))
    setCopied(true)
    setTimeout(() => setCopied(false), 1500)
  }

  return (
    <button className="articles-share-btn" onClick={handleCopy} title="Copy link">
      <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
        <path d="M10 13a5 5 0 007.54.54l3-3a5 5 0 00-7.07-7.07l-1.72 1.71" />
        <path d="M14 11a5 5 0 00-7.54-.54l-3 3a5 5 0 007.07 7.07l1.71-1.71" />
      </svg>
      {copied ? 'Copied!' : 'Copy Link'}
    </button>
  )
}

/**
 * /articles/{slug} rendered from the route payload (react-ssr Task 13):
 * the first render — the one renderToString and every crawler sees — is
 * the complete journal, no fetch, no hash routing. body_html is the
 * pipeline's Python-markdown rendering, injected verbatim.
 */
function ArticleFromPayload({ article }: { article: ArticleRoute }) {
  const isFounder = useIsFounder()
  // Dasselbe Inhaltsverzeichnis wie in der SPA-Ansicht — die hatte es seit
  // jeher, die indexierte Ansicht nicht, obwohl gerade dort die langen
  // Ausgaben liegen.
  const headings = useMemo(() => extractHtmlHeadings(article.body_html), [article.body_html])
  const activeHeading = useActiveHeading(headings, true)

  return (
    <div className="articles-page">
      <PageHeader currentPage="articles">
        <a className="articles-page-back-btn" href="/articles/">
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
            <polyline points="15 18 9 12 15 6" />
          </svg>
          All Journals
        </a>
      </PageHeader>
      <AiNoticeBanner message="This journal's text is AI-generated from YouTube video content; images are from the original sources. Always verify with original sources." />
      <main className="articles-page-content">
        {/* Ohne TOC: einspaltig. Das Grid ist 220px + 720px, die SEO-Ansicht
            rendert aber kein Inhaltsverzeichnis — der Artikel landete als
            einziges Kind in der 220px-Spalte und wurde auf seine
            Mindestbreite gequetscht (gemessen: 359px statt 720px). Sichtbar
            wurde das erst, als die Bildbegrenzung die Box nicht mehr
            künstlich aufspannte. */}
        <div className={`articles-reader-layout${headings.length > 0 ? '' : ' is-solo'}`}>
          <TableOfContents headings={headings} activeSlug={activeHeading} />
          <JournalArticle
            article={article}
            lead={
              <Breadcrumbs
                trail={[
                  { name: 'Home', path: '/' },
                  { name: 'Journal', path: '/articles/' },
                  { name: article.title },
                ]}
              />
            }
            actions={
              <div className="articles-reader-meta-actions">
                <ShareButton article={article} />
                <CopyLinkButton article={article} />
                {isFounder && <MediumButton article={article} />}
              </div>
            }
          >
            {article.quality_report && (
              <JournalQualityReportPanel report={article.quality_report} />
            )}
            <footer className="articles-reader-footer">
              <ThumbsFeedback
                prompt="journal_end"
                target={slugify(article.title)}
                question="Was this journal useful?"
                placeholder="What was missing?"
                extra={{ journal: slugify(article.title) }}
              />
              <a className="articles-reader-back-link" href="/articles/">
                ← All journals
              </a>
            </footer>
          </JournalArticle>
        </div>
        <CommunityCta />
      </main>
    </div>
  )
}

/** /articles/ rendered from the route payload — the crawlable journal hub. */
function ArticleIndexFromPayload({ route }: { route: ArticleIndexRoute }) {
  return (
    // articles-page / articles-page-content, nicht story-page / story-main:
    // .story-main ist die 820-px-Lesespalte einer Story und .story-page erzwingt
    // height:100vh mit eigenem Scrollbereich. Beides quetschte den Hub (Hero
    // 900 px, Grid 1100 px) in eine Lesebreite. Der Journal-Hub steht in
    // denselben Containern wie die Artikel-Seite und wie die alte /articles.html.
    <div className="articles-page">
      <PageHeader currentPage="articles">
        <span className="page-header-title">Weekly Journal</span>
      </PageHeader>
      <AiNoticeBanner message="Journal text is AI-generated from YouTube video content; images are from the original sources. Always verify with original sources." />
      <main className="articles-page-content">
        <Breadcrumbs trail={[{ name: 'Home', path: '/' }, { name: 'Journal' }]} />
        <h1 className="story-title">Weekly Archaeology Journal</h1>
        <div className="story-meta">{route.articles.length} issues</div>
        <JournalHub cards={route.articles} />
        <CommunityCta />
      </main>
    </div>
  )
}

export default function ArticlesPage() {
  // Registry entry for both journal route types. Without a payload the URL is
  // the legacy /articles.html entry, which only forwards to the pages that
  // exist (ArticlesLegacyRedirect).
  const route = useRoute()
  if (route?.type === 'article') return <ArticleFromPayload article={route} />
  if (route?.type === 'articleIndex') return <ArticleIndexFromPayload route={route} />
  return <ArticlesLegacyRedirect />
}


/**
 * /articles.html was the standalone reader's entry until 2026-10-17. It now
 * only forwards: the hub lives at /articles/ and one issue at /articles/{slug},
 * so a visitor who kept the old link lands on the page that answers it.
 *
 * The fragment IS the slug the canonical URL is built from (articlePath =
 * `/articles/${slugify(title)}`), so `#sacsayhuamán` becomes
 * `/articles/sacsayhuamán` — the percent-encoded form is decoded first, the
 * same way articleForHash read it.
 *
 * The redirect runs here and not on the server: a fragment never reaches the
 * server, so no 301 can see it. A fragment that is not a slug (`#%`, `#a b`)
 * names no journal and goes to the hub, as the reader's resolveHash did.
 */
function ArticlesLegacyRedirect() {
  useEffect(() => {
    window.location.replace(legacyTarget(window.location.hash))
  }, [])
  return null
}

/** Where /articles.html#fragment leads. Exported for its test. */
export function legacyTarget(hash: string): string {
  const raw = hash.replace(/^#/, '')
  if (!raw) return '/articles/'
  let slug: string
  try {
    slug = decodeURIComponent(raw)
  } catch (e) {
    if (e instanceof URIError) return '/articles/'
    throw e
  }
  // slugify keeps letters, digits, '_' and '-'; anything else names no journal.
  return /^[\p{L}\p{N}_-]+$/u.test(slug) ? `/articles/${slug}` : '/articles/'
}
